export const title = "Periodic Report Usage Guide";
export const html = "<h1>Periodic Report Usage Guide</h1>\n      <hr class=\"rule\" />\n      <p>You can periodically report the count values being collected by a configured counter to storage destinations such as FTP, Email, or AWS S3.</p>\n      <p>Each counter app includes a separate menu for configuring reports.</p>\n      \n<div class=\"figure\">\n<div class=\"app-window\">\n  <div class=\"app-main\" style=\"padding:0;\">\n    <div class=\"app-breadcrumb\" style=\"padding:14px 18px 0;\">Home / Application / Occupancy Counting / Report</div>\n    <div class=\"app-h\" style=\"padding:0 18px;\">Report</div>\n    <div style=\"padding:0 18px;display:flex;gap:8px;margin-bottom:10px;\">\n      <span class=\"btn small\">Counter</span><span class=\"btn small\">Event-Action</span><span class=\"btn small primary\">Report</span>\n    </div>\n    <div class=\"app-panel\" style=\"margin:0 18px 18px;\"><strong style=\"font-size:12.5px;\">Report (2)</strong></div>\n  </div>\n</div>\n<figcaption>Occupancy Counting &rarr; Report tab</figcaption>\n</div>\n\n      <p>Click the button at the top right of the report list to add a new counter rule.</p>\n      <div class=\"figure\" style=\"max-width:180px;\"><span class=\"btn small primary\">+ Add Report</span></div>\n\n      <h2>Basic Report Settings</h2>\n      \n<div class=\"figure\">\n<div class=\"app-panel\" style=\"max-width:480px;\">\n  <div class=\"form-grid\" style=\"grid-template-columns:110px 1fr;font-size:12.5px;\">\n    <span>Report Name</span><input value=\"Report #4547\" disabled>\n    <span>&#9432; Enable</span><span style=\"background:#2653d6;border-radius:10px;width:34px;height:18px;display:inline-block;position:relative;\"><span style=\"position:absolute;right:2px;top:2px;width:14px;height:14px;background:#fff;border-radius:50%;\"></span></span>\n    <span>Counter</span><span><select disabled style=\"width:auto;\"><option>All</option></select> <label style=\"font-size:11.5px;margin-left:6px;\"><input type=\"checkbox\" disabled> Combine into one file &#9432;</label></span>\n    <span>Data Format</span><select disabled><option>CSV</option><option>JSON</option></select>\n  </div>\n</div>\n</div>\n\n      <ol>\n        <li>Enter a name in <strong>Report Name</strong> to distinguish this report configuration. A random default value is pre-filled \u2014 edit it if needed.</li>\n        <li>Once you set the <strong>Report Name</strong>, you can reference it in the recipient settings for the report file or directory name using the <code>{{REPORT NAME}}</code> token.</li>\n        <li>If you want the report feature to be active as soon as it's created, turn on the <strong>Enable</strong> switch.</li>\n        <li>The <strong>Counter</strong> setting specifies which counter the report covers. A counter must already be configured. Selecting <strong>All</strong> makes every configured counter a target of the report.</li>\n        <li>The <strong>Data Format</strong> setting specifies the type of report data. Data can be reported in CSV or JSON format.</li>\n      </ol>\n\n      <h2>Schedule Settings</h2>\n      <p>Schedule settings let you configure the report interval, report time, the range of data covered, and the data aggregation unit. You can register multiple schedules, and each registered schedule sends data independently.</p>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:420px;margin:0 auto;\">\n  <div class=\"modal-head\">Schedule Settings</div>\n  <div class=\"modal-body\">\n    <div class=\"form-grid\" style=\"grid-template-columns:100px 1fr;font-size:12.5px;\">\n      <span>Report Period</span><select disabled><option>Every Hour</option></select>\n      <span>Report Time</span><span><select disabled style=\"width:60px;\"><option>00</option></select> : <select disabled style=\"width:60px;\"><option>00</option></select></span>\n      <span>Data</span><select disabled><option>All Hours</option></select>\n      <span>Unit</span><select disabled><option>5 min</option></select>\n    </div>\n  </div>\n  <div class=\"modal-foot\"><span class=\"btn small\">Close</span> <span class=\"btn small primary\">Apply</span></div>\n</div>\n<figcaption>Schedule settings</figcaption>\n</div>\n\n      <ol>\n        <li><strong>Report Period</strong> sets how often the data report runs.</li>\n        <li><strong>Report Time</strong> sets when the report runs relative to the report period.</li>\n        <li><strong>Data</strong> sets the range of data covered by the report.</li>\n        <li><strong>Unit</strong> sets the unit used to aggregate the report data.</li>\n      </ol>\n\n      <h2>Recipient Settings</h2>\n      <p>Recipient settings work similarly to the action settings in event action rule configuration. You can configure the destination for delivering the report.</p>\n      <p>Supported file transfer protocols include FTP(SFTP), Email, and AWS S3.</p>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;gap:8px;\">\n    <span class=\"btn small\">HTTP/FTP</span><span class=\"btn small\">Email</span><span class=\"btn small\">AWS S3</span>\n  </div>\n</div>\n</div>\n\n      <p>For detailed configuration steps, see the <a href=\"#\">Action Setting Guide</a>.</p>\n\n      <h2>Finishing Setup</h2>\n      <p>Once you've finished the basic settings, schedule settings, and recipient settings, click the button at the very bottom of the page to submit the report settings.</p>\n      <div class=\"figure\" style=\"max-width:120px;\"><span class=\"btn small primary\">Save</span></div>\n      <p>If the settings were applied successfully, you can see the item in the list on the counter report screen.</p>";
